import json
from typing import Any, Dict, Tuple, Optional, List

import jax
import jax.numpy as jnp
from jax import random as jr
import flax.linen as nn
import optax

# Stubs for loader (unused by test())
class _NullNet(nn.Module):
    @nn.compact
    def __call__(self, x, done, rnn_state=None):
        B = x.shape[0]
        z = x.reshape((B, -1))
        h = nn.Dense(16, kernel_init=nn.initializers.xavier_uniform())(z)
        h = nn.relu(h)
        policy_logits = nn.Dense(4, kernel_init=nn.initializers.xavier_uniform())(h)
        value = nn.Dense(1, kernel_init=nn.initializers.xavier_uniform())(h).squeeze(-1)
        return policy_logits, value, {"h": jnp.zeros((B,))}

def create_network(hparams: Dict[str, Any] = None):
    return _NullNet()

def create_optimizer(learning_rate: float = 4e-4):
    return optax.adam(learning_rate)

# PG backbone with LN-gated ConvLSTM
class BottleneckDilatedBlock(nn.Module):
    features: int
    bottleneck_ratio: float = 0.28
    dilation: int = 6
    @nn.compact
    def __call__(self, x):
        mid = max(1, int(self.features * self.bottleneck_ratio))
        y = nn.Conv(mid, (1,1), padding='SAME',
                    kernel_init=nn.initializers.xavier_uniform())(x)
        y = nn.relu(y)
        y = nn.Conv(mid, (3,3), padding='SAME',
                    kernel_dilation=(self.dilation, self.dilation),
                    kernel_init=nn.initializers.xavier_uniform())(y)
        y = nn.relu(y)
        y = nn.Conv(self.features, (1,1), padding='SAME',
                    kernel_init=nn.initializers.xavier_uniform())(y)
        return nn.relu(x + y)

class ConvLSTMCellLN(nn.Module):
    features: int
    kernel_size: Tuple[int,int] = (3,3)
    @nn.compact
    def __call__(self, carry, x):
        h, c = carry
        gates_lin = nn.Conv(4*self.features, self.kernel_size, padding='SAME',
                            kernel_init=nn.initializers.xavier_uniform())(
            jnp.concatenate([x, h], axis=-1))
        gates_ln = nn.LayerNorm(epsilon=1e-5)(gates_lin)
        i_lin, f_lin, g_lin, o_lin = jnp.split(gates_ln, 4, axis=-1)
        i = jax.nn.sigmoid(i_lin); f = jax.nn.sigmoid(f_lin); o = jax.nn.sigmoid(o_lin); g = jnp.tanh(g_lin)
        c = f * c + i * g
        h = o * jnp.tanh(c)
        gates = {"i_lin": i_lin, "f_lin": f_lin, "g_lin": g_lin, "o_lin": o_lin}
        return (h, c), h, gates

class FeatureExtractor(nn.Module):
    cnn1: int = 32
    cnn2: int = 64
    convlstm: int = 64
    dilation: int = 6
    bottleneck_ratio: float = 0.28
    @nn.compact
    def __call__(self, x, done, rnn_state=None):
        B = x.shape[0]
        x = nn.Conv(self.cnn1, (3,3), padding='SAME',
                    kernel_init=nn.initializers.xavier_uniform())(x); x = nn.relu(x)
        x = BottleneckDilatedBlock(self.cnn1, self.bottleneck_ratio, self.dilation)(x)
        x = nn.Conv(self.cnn2, (3,3), padding='SAME',
                    kernel_init=nn.initializers.xavier_uniform())(x); x = nn.relu(x)
        x = BottleneckDilatedBlock(self.cnn2, self.bottleneck_ratio, self.dilation)(x)
        if rnn_state is None:
            zeros = lambda: jnp.zeros((B, 8, 8, self.convlstm), dtype=x.dtype)
            rnn_state = {'h': zeros(), 'c': zeros()}
        if done is not None:
            m = (1.0 - done.reshape(B,1,1,1).astype(x.dtype))
            rnn_state = {'h': rnn_state['h'] * m, 'c': rnn_state['c'] * m}
        (h_new, c_new), h_out, gates = ConvLSTMCellLN(self.convlstm)((rnn_state['h'], rnn_state['c']), x)
        rnn_state = {'h': h_new, 'c': c_new}
        return h_out, gates, rnn_state

class AttnPool(nn.Module):
    @nn.compact
    def __call__(self, h_out):
        B, H, W, C = h_out.shape
        logits = nn.Conv(1, (1,1), padding='SAME',
                         kernel_init=nn.initializers.xavier_uniform())(h_out)  # (B,H,W,1)
        weights = jax.nn.softmax(logits.reshape((B, H*W)), axis=-1).reshape((B, H*W, 1))
        tokens = h_out.reshape((B, H*W, C))
        attn_vec = (weights * tokens).sum(axis=1)   # (B,C)
        return attn_vec, weights

# Head-only readouts on z
class DualHeadReadout(nn.Module):
    head_hidden: int = 64
    @nn.compact
    def __call__(self, z):  # z: (B,2C)
        shared = nn.Dense(256, kernel_init=nn.initializers.xavier_uniform())(z); shared = nn.relu(shared)
        ph = nn.Dense(self.head_hidden, kernel_init=nn.initializers.xavier_uniform())(shared); ph = nn.relu(ph)
        policy_logits = nn.Dense(4, kernel_init=nn.initializers.xavier_uniform())(ph)
        vh = nn.Dense(self.head_hidden, kernel_init=nn.initializers.xavier_uniform())(shared); vh = nn.relu(vh)
        value = nn.Dense(1, kernel_init=nn.initializers.xavier_uniform())(vh).squeeze(-1)
        return policy_logits, value

class SimpleHeadReadout(nn.Module):
    @nn.compact
    def __call__(self, z):  # z: (B,C)
        shared = nn.Dense(256, kernel_init=nn.initializers.xavier_uniform())(z); shared = nn.relu(shared)
        policy_logits = nn.Dense(4, kernel_init=nn.initializers.xavier_uniform())(shared)
        value = nn.Dense(1, kernel_init=nn.initializers.xavier_uniform())(shared).squeeze(-1)
        return policy_logits, value

class GapOnlyReadout(nn.Module):
    @nn.compact
    def __call__(self, z):  # z: (B,C)
        shared = nn.Dense(256, kernel_init=nn.initializers.xavier_uniform())(z); shared = nn.relu(shared)
        policy_logits = nn.Dense(4, kernel_init=nn.initializers.xavier_uniform())(shared)
        value = nn.Dense(1, kernel_init=nn.initializers.xavier_uniform())(shared).squeeze(-1)
        return policy_logits, value

# Synthetic batch
def generate_synth(key, B=32):
    k1, k2, k3 = jr.split(key, 3)
    labels = jr.randint(k1, (B, 8, 8), 0, 7)
    oh = jax.nn.one_hot(labels, 7)
    noise_mask = jr.bernoulli(k2, 0.10, (B,8,8,1))
    noise_lbl = jr.randint(k3, (B,8,8), 0, 7)
    noise_oh = jax.nn.one_hot(noise_lbl, 7)
    ch07 = jnp.where(noise_mask > 0.5, noise_oh, oh)
    time_ch = jr.uniform(jr.fold_in(key, 123), (B,8,8,1))
    x = jnp.concatenate([ch07, time_ch], axis=-1)
    done = jnp.zeros((B,), dtype=jnp.float32)
    return x, done

def attn_entropy_topk(w: Optional[jnp.ndarray], k=5):
    if w is None:
        return None
    w = w.squeeze(-1)
    eps = 1e-8
    H = -jnp.sum(w * jnp.log(jnp.clip(w, eps, 1.0)), axis=1)
    topk = jnp.sort(w, axis=1)[:, -k:]
    topk_mass = jnp.sum(topk, axis=1)
    return {"entropy_mean": float(jnp.mean(H)),
            "entropy_std": float(jnp.std(H)),
            "top5_mass_mean": float(jnp.mean(topk_mass))}

def gate_stats(gates: Dict[str, jnp.ndarray]):
    def _sat_sig(x):
        p = jax.nn.sigmoid(x)
        return jnp.mean((p < 0.05).astype(jnp.float32)), jnp.mean((p > 0.95).astype(jnp.float32))
    def _sat_tanh(x):
        return jnp.mean((jnp.abs(jnp.tanh(x)) > 0.9).astype(jnp.float32))
    out = {}
    for name in ["i_lin","f_lin","o_lin","g_lin"]:
        x = gates[name]
        if name == "g_lin":
            out["g"] = {"mean": float(jnp.mean(x)), "std": float(jnp.std(x)), "sat": float(_sat_tanh(x))}
        else:
            lo, hi = _sat_sig(x)
            out[name[0]] = {"mean": float(jnp.mean(x)), "std": float(jnp.std(x)),
                            "sat_low": float(lo), "sat_high": float(hi)}
    return out

def spectral_norms(params: Dict[str, Any], iters=10):
    specs: List[float] = []
    def _power_iter(W, iters=10):
        v = jnp.ones((W.shape[1],), dtype=W.dtype)
        v = v / (jnp.linalg.norm(v) + 1e-8)
        for _ in range(iters):
            v = W.T @ (W @ v)
            v = v / (jnp.linalg.norm(v) + 1e-8)
        return jnp.linalg.norm(W @ v)
    def _walk(d):
        for _,v in d.items():
            if isinstance(v, dict):
                if 'kernel' in v and isinstance(v['kernel'], jnp.ndarray) and v['kernel'].ndim == 2:
                    specs.append(float(_power_iter(v['kernel'], iters)))
                _walk(v)
    _walk(params)
    if not specs:
        return {"dense_spec_max": None, "dense_spec_mean": None}
    arr = jnp.array(specs)
    return {"dense_spec_max": float(jnp.max(arr)), "dense_spec_mean": float(jnp.mean(arr))}

def grad_z_norm(model, variables, z):
    def f(inp):
        logits, _ = model.apply(variables, inp)
        return jnp.sum(logits)
    g = jax.grad(f)(z)
    l2 = jnp.sqrt(jnp.sum(g*g, axis=1))
    z_l2 = jnp.sqrt(jnp.sum(z*z, axis=1)) + 1e-8
    return float(jnp.mean(l2)), float(jnp.mean(l2 / z_l2))

def run_v2(key):
    # Shared features
    B = 32
    x, done = generate_synth(key, B=B)
    feat = FeatureExtractor()
    fvars = feat.init(jr.fold_in(key, 0), x, done, None)
    h_out, gates, _ = feat.apply(fvars, x, done, None)

    # Attention pooling via Module (init/apply)
    ap = AttnPool()
    ap_vars = ap.init(jr.fold_in(key, 55), h_out)
    attn_vec, attn_w = ap.apply(ap_vars, h_out)

    gap_vec = h_out.mean(axis=(1,2))
    z_dual = jnp.concatenate([attn_vec, gap_vec], axis=-1)  # (B, 2C)
    z_attn = attn_vec  # (B, C)
    z_gap  = gap_vec   # (B, C)

    # Head-only readouts (initialized independently)
    dual = DualHeadReadout(head_hidden=64)
    simp = SimpleHeadReadout()
    gap  = GapOnlyReadout()

    dvars = dual.init(jr.fold_in(key, 101), z_dual)
    svars = simp.init(jr.fold_in(key, 102), z_attn)
    gvars = gap.init(jr.fold_in(key, 103), z_gap)

    # Spectral norms
    d_spec = spectral_norms(dvars.get("params", {}))
    s_spec = spectral_norms(svars.get("params", {}))
    g_spec = spectral_norms(gvars.get("params", {}))

    # z→logits gradient norms (absolute and normalized)
    d_g_abs, d_g_rel = grad_z_norm(dual, dvars, z_dual)
    s_g_abs, s_g_rel = grad_z_norm(simp, svars, z_attn)
    g_g_abs, g_g_rel = grad_z_norm(gap,  gvars, z_gap)

    # Attention and gate stats (from shared backbone)
    a_stats = attn_entropy_topk(attn_w)
    g_stats = gate_stats(gates)

    return {
        "seed": 42,
        "batch": [B, 8, 8, 8],
        "z_dims": {"dual": int(z_dual.shape[1]), "simple": int(z_attn.shape[1]), "gap": int(z_gap.shape[1])},
        "models": {
            "dual_attn_gap_deep": {
                "z_grad_l2_mean": d_g_abs, "z_grad_rel_mean": d_g_rel, "dense_spectral_norm": d_spec
            },
            "simple_head_attn": {
                "z_grad_l2_mean": s_g_abs, "z_grad_rel_mean": s_g_rel, "dense_spectral_norm": s_spec
            },
            "gap_only_head": {
                "z_grad_l2_mean": g_g_abs, "z_grad_rel_mean": g_g_rel, "dense_spectral_norm": g_spec
            }
        },
        "attn": a_stats if a_stats is not None else "n/a",
        "gate_stats": g_stats
    }

def test():
    out = run_v2(jr.PRNGKey(42))
    print(json.dumps(out, indent=2))
    return "OK"

